INSERT INTO _migration_349_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_ga_b005_001' AND NOT (q.topic_id IS 'topic_was_ga_b005_1' AND q.subject_id IS 'subj_wassce_ga' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Ga: Why must ɔ and o be distinguished in standard Ga writing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They represent different vowel qualities and can distinguish words","B. They represent different vowel qualities required by the orthography","C. By writing the relevant vowel letter twice","D. Joining or separating forms wrongly can obscure grammar and meaning"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives. Therefore the correct answer is A: They represent different vowel qualities and can distinguish words.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_ga_b005_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_ga_b005_001' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Ga practice aligned to official Ghana curriculum and WAEC examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_bo